// 原DrillChallenge确定性纯规则；分数仅在冻结快照上计算，所有确认必须绑定当前步和待选值。
#include "drill_model.hpp"
#include "resident/model/common_model.hpp"
#include <algorithm>
#include <charconv>
#include <set>
namespace hanmo::resident {
namespace {
bool cell(HexPoint p){return p.q>=0&&p.q<5&&p.r>=0&&p.r<4;}
bool contains(const std::vector<HexPoint>& a,HexPoint p){return std::find(a.begin(),a.end(),p)!=a.end();}
bool cells(const std::vector<HexPoint>& a){if(a.empty()||a.size()>20)return false;std::set<std::pair<Integer,Integer>> seen;for(auto p:a)if(!cell(p)||!seen.insert({p.q,p.r}).second)return false;return true;}
bool local(const StableId& s,std::size_t max){if(s.empty()||s.size()>max||s[0]<'a'||s[0]>'z')return false;for(char c:s)if(!(c>='a'&&c<='z')&&!(c>='0'&&c<='9')&&c!='_'&&c!='.'&&c!='-')return false;return true;}
bool symbol(const StableId& s,bool qualified=false){auto p=s.find("::");if(p==StableId::npos)return local(s,80);return qualified&&s.find("::",p+2)==StableId::npos&&local(s.substr(0,p),32)&&local(s.substr(p+2),80);}
// UTF-8来源已经过边界解码；Godot长度按Unicode码点而非字节计算。
bool text(const StableId& key,const StableId& value){std::size_t count=0;for(unsigned char ch:value)if((ch&0xc0)!=0x80)++count;return symbol(key,true)&&!value.empty()&&count<=4096;}
bool seed(const StableId& s){Integer x=0;auto r=std::from_chars(s.data(),s.data()+s.size(),x);return r.ec==std::errc()&&r.ptr==s.data()+s.size()&&std::to_string(x)==s;}
bool snapshot(const DrillSnapshot& s){return s.skill_level>=0&&s.skill_level<=4&&s.auxiliary_attribute>=1&&s.auxiliary_attribute<=110;}
// 来源绑定接受原Unicode短标识，禁止换行或借另一位人物重开实例。
bool binding(const DrillState& s){std::size_t count=0;for(unsigned char ch:s.source_id)if((ch&0xc0)!=0x80)++count;return symbol(s.actor_id,true)&&!s.source_id.empty()&&count<=160&&s.source_id.find_first_of("\n\r")==StableId::npos;}
Status fail(const StableId& code){return common_failure(code);}
template<class T>Outcome<T> error(const StableId& code){return {false,{},fail(code).error};}
const DrillGroup* group(const DrillDefinition& d,const StableId& id){for(auto& g:d.groups)if(g.id==id)return &g;return nullptr;}
bool group_kind(const DrillDefinition& d,const StableId& id,const StableId& kind){auto g=group(d,id);return g&&g->kind==kind;}
using Board=std::vector<std::pair<StableId,HexPoint>>;
Board origins(const DrillDefinition& d){Board b;for(auto& g:d.groups)b.emplace_back(g.id,g.origin);return b;}
const HexPoint* point(const Board& b,const StableId& id){for(auto& p:b)if(p.first==id)return &p.second;return nullptr;}
Outcome<DrillMove> apply(const DrillDefinition& d,Board& b,const StableId& id,HexPoint target){auto from=point(b,id);if(!cell(target)||!from)return error<DrillMove>("InvalidDrillTarget");auto g=group(d,id);if(!g||!contains(g->targets,target)||*from==target)return error<DrillMove>("DrillTargetNotAllowed");for(auto& p:b)if(p.first!=id&&p.second==target)return error<DrillMove>("DrillCellOccupied");DrillMove move{id,*from,target,{}};for(auto& p:b)if(p.first==id)p.second=target;return {true,move,{}};}
Outcome<Board> replay(const DrillDefinition& d,const std::vector<DrillMove>& moves){if(moves.size()>4)return error<Board>("InvalidDrillMoves");auto board=origins(d);for(auto& m:moves){if(!cell(m.from)||!cell(m.target))return error<Board>("InvalidDrillMove");auto moved=apply(d,board,m.group_id,m.target);if(!moved.ok||moved.value.from!=m.from)return error<Board>("InvalidDrillMove");}return {true,board,{}};}
DrillObjectives objectives(const DrillDefinition& d,const Board& b,const std::vector<DrillMove>& moves){DrillObjectives o;o.supply=contains(d.supply.guard_cells,*point(b,d.supply.group_id));o.passage=contains(d.passage.cells,*point(b,d.passage.group_id));for(auto& p:d.screen.pairs)if(*point(b,d.screen.front_group_id)==p.front&&*point(b,d.screen.ranged_group_id)==p.rear)o.screen=true;o.cavalry=!contains(d.cavalry.bad_cells,group(d,d.cavalry.group_id)->origin);for(auto& m:moves)if(m.group_id==d.cavalry.group_id&&contains(d.cavalry.bad_cells,m.target))o.cavalry=false;return o;}
Integer score(const DrillObjectives& o){return 25*(Integer(o.supply)+Integer(o.passage)+Integer(o.screen)+Integer(o.cavalry));}
DrillResult result(const DrillDefinition& d,const DrillState& s,const StableId& completion){DrillResult r;r.completion=completion;r.auto_score=std::clamp<Integer>(45+8*s.actor_snapshot.skill_level+s.actor_snapshot.auxiliary_attribute/10-8*d.difficulty,30,90);r.score=r.auto_score;if(completion=="manual"){r.objectives=objectives(d,replay(d,s.moves).value,s.moves);r.raw_score=score(*r.objectives);r.score=std::max(*r.raw_score,r.auto_score-10);}r.performance_bp=std::min<Integer>(12000,10000+std::max<Integer>(0,r.score-r.auto_score)*200);r.choices=s.moves;return r;}
bool move_equal(const DrillMove& a,const DrillMove& b){return a.group_id==b.group_id&&a.from==b.from&&a.target==b.target;}
bool result_equal(const DrillResult& a,const DrillResult& b){if(a.completion!=b.completion||a.score!=b.score||a.raw_score!=b.raw_score||a.auto_score!=b.auto_score||a.performance_bp!=b.performance_bp||a.objectives.has_value()!=b.objectives.has_value()||a.choices.size()!=b.choices.size())return false;if(a.objectives){auto& x=*a.objectives;auto& y=*b.objectives;if(x.supply!=y.supply||x.passage!=y.passage||x.screen!=y.screen||x.cavalry!=y.cavalry)return false;}for(std::size_t i=0;i<a.choices.size();++i)if(!move_equal(a.choices[i],b.choices[i]))return false;return true;}
Status active(const DrillDefinition& d,const DrillState& s,Integer step){auto r=validate_drill_state(d,s);if(!r.ok)return r;if(s.phase!="active")return fail("DrillAlreadyCompleted");if(step<1||step>4||step!=Integer(s.moves.size())+1)return fail("StaleDrillStep");return common_success();}
}
Status validate_drill_definition(const DrillDefinition& d){if(!symbol(d.id,true)||d.difficulty<0||d.difficulty>3||!text(d.prompt_key,d.prompt)||d.groups.size()!=3||d.solution.size()!=4)return fail("InvalidDrillDefinition");std::set<StableId> ids,kinds;std::set<std::pair<Integer,Integer>> occupied;for(auto& g:d.groups){if(!symbol(g.id)||!ids.insert(g.id).second||(g.kind!="foot"&&g.kind!="ranged"&&g.kind!="cavalry")||!kinds.insert(g.kind).second||!text(g.text_key,g.text)||!cell(g.origin)||!occupied.insert({g.origin.q,g.origin.r}).second||!cells(g.targets))return fail("InvalidDrillGroup");}if(!group_kind(d,d.supply.group_id,"foot")||!cell(d.supply.point)||!cells(d.supply.guard_cells))return fail("InvalidDrillSupplyGoal");if(!group(d,d.passage.group_id)||!cells(d.passage.cells))return fail("InvalidDrillPassageGoal");if(!group_kind(d,d.screen.front_group_id,"foot")||!group_kind(d,d.screen.ranged_group_id,"ranged")||d.screen.pairs.empty()||d.screen.pairs.size()>400)return fail("InvalidDrillScreenGoal");std::set<std::array<Integer,4>> seen;for(auto& p:d.screen.pairs)if(!cell(p.front)||!cell(p.rear)||p.front==p.rear||!seen.insert({p.front.q,p.front.r,p.rear.q,p.rear.r}).second)return fail("InvalidDrillScreenGoal");if(!group_kind(d,d.cavalry.group_id,"cavalry")||!cells(d.cavalry.bad_cells))return fail("InvalidDrillCavalryGoal");if(!text(d.supply.text_key,d.supply.text)||!text(d.passage.text_key,d.passage.text)||!text(d.screen.text_key,d.screen.text)||!text(d.cavalry.text_key,d.cavalry.text))return fail("MissingDrillObjectiveText");auto b=origins(d);std::vector<DrillMove> moves;for(auto& p:d.solution){auto applied=apply(d,b,p.group_id,p.target);if(!applied.ok)return fail("InvalidDrillSolution");moves.push_back(applied.value);}if(score(objectives(d,b,moves))!=100)return fail("UnsolvedDrillTemplate");return common_success();}
Status validate_drill_state(const DrillDefinition& d,const DrillState& s){auto r=validate_drill_definition(d);if(!r.ok)return r;if(s.format!="HM-DRILL-CHALLENGE/1"||s.definition_id!=d.id||!binding(s)||!snapshot(s.actor_snapshot)||!seed(s.seed)||(s.mode!="manual"&&s.mode!="automatic")||(s.phase!="active"&&s.phase!="completed"))return fail("InvalidDrillState");if(s.source_sha256!=d.source_sha256)return fail("DrillSourceChanged");auto played=replay(d,s.moves);if(!played.ok)return {false,{},played.error};if(s.phase=="active"){if(s.mode!="manual"||s.moves.size()>=4||s.result)return fail("InvalidDrillProgress");if(s.pending&&!apply(d,played.value,s.pending->group_id,s.pending->target).ok)return fail("InvalidDrillPending");return common_success();}if(s.pending)return fail("InvalidDrillPending");if(!s.result)return fail("InvalidDrillResult");auto completion=s.result->completion;if((completion!="manual"&&completion!="automatic"&&completion!="exited")||(completion=="manual"&&(s.mode!="manual"||s.moves.size()!=4))||(completion=="automatic"&&(s.mode!="automatic"||!s.moves.empty()))||(completion=="exited"&&(s.mode!="manual"||s.moves.size()>=4)))return fail("InvalidDrillResult");if(!replay(d,s.result->choices).ok||!result_equal(*s.result,result(d,s,completion)))return fail("InvalidDrillResult");return common_success();}
Outcome<DrillState> create_drill(const DrillDefinition& d,const StableId& actor,const StableId& source,const DrillSnapshot& snap,const StableId& random,const StableId& mode){auto r=validate_drill_definition(d);if(!r.ok)return {false,{},r.error};DrillState s;s.definition_id=d.id;s.source_sha256=d.source_sha256;s.actor_id=actor;s.source_id=source;s.actor_snapshot=snap;s.seed=random;s.mode=mode;if(!binding(s)||!snapshot(snap)||!seed(random)||(mode!="manual"&&mode!="automatic"))return error<DrillState>("InvalidDrillStart");if(mode=="automatic"){s.phase="completed";s.result=result(d,s,"automatic");}return {true,s,{}};}
Outcome<DrillState> draft_drill_move(const DrillDefinition& d,const DrillState& s,Integer step,const StableId& id,HexPoint target){auto r=active(d,s,step);if(!r.ok)return {false,{},r.error};auto board=replay(d,s.moves).value;auto move=apply(d,board,id,target);if(!move.ok)return {false,{},move.error};auto next=s;next.pending=DrillPending{id,target,{}};return {true,next,{}};}
Outcome<DrillState> cancel_drill_pending(const DrillDefinition& d,const DrillState& s,Integer step,const DrillPending& p){auto r=active(d,s,step);if(!r.ok)return {false,{},r.error};if(!cell(p.target)||!s.pending||p.group_id!=s.pending->group_id||p.target!=s.pending->target)return error<DrillState>("StaleDrillPending");auto next=s;next.pending.reset();return {true,next,{}};}
Outcome<DrillState> confirm_drill_move(const DrillDefinition& d,const DrillState& s,Integer step,const DrillPending& p){auto r=active(d,s,step);if(!r.ok)return {false,{},r.error};if(!cell(p.target)||!s.pending||p.group_id!=s.pending->group_id||p.target!=s.pending->target)return error<DrillState>("StaleDrillPending");auto board=replay(d,s.moves).value;auto move=apply(d,board,p.group_id,p.target);if(!move.ok)return {false,{},move.error};auto next=s;next.moves.push_back(move.value);next.pending.reset();if(next.moves.size()==4){next.phase="completed";next.result=result(d,next,"manual");}return {true,next,{}};}
Outcome<DrillState> exit_drill(const DrillDefinition& d,const DrillState& s){auto r=validate_drill_state(d,s);if(!r.ok)return {false,{},r.error};auto next=s;if(s.phase=="active"){next.phase="completed";next.pending.reset();next.result=result(d,next,"exited");}return {true,next,{}};}
}
